xml.src:

import {InuToggle} from 'inugami-ng/components/inu-toggle';

interface MyFormModel {
  sms: boolean;
  email: boolean;
  mail: boolean;
  inApp: boolean;
}


@Component({
//...
 imports: [
   InuToggle,
   FormField
 ]
})
export class MyView {

 formModel = signal<MyFormModel>({
                                    sms: false,
                                    email: true,
                                    inApp: false,
                                    mail: false
                                  });

  myForm = form(this.formModel, (path) => {
    required(path.sms);
  });

  constructor() {
    toObservable(this.formModel)
      .pipe(
        debounceTime(200),
        distinctUntilChanged(),
        takeUntilDestroyed()
      )
      .subscribe(value => {
        this.onValueChanged(value)
      });
  }
}
